{
  "packet_id": "H6-T02-2",
  "claim_id": "C021",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C021",
    "value": "Nested trace spans should not be counted as independent evidence.",
    "scope": "A restriction on evidential independence, not a claim that nested spans are unusable.",
    "provenance": {
      "refs": [
        {
          "source_id": "P010",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P010 directly supplies the restriction on treating nested spans as independent evidence."
    }
  },
  "signal_basis": {
    "component_id": "C021_signal_basis",
    "value": "The comparison evaluates trace evidence across hypotheses for consistency, reliability and diagnostic value; nested spans and dependent measurements can distort that comparison if counted independently.",
    "scope": "Evidence weighting in the export investigation's hypothesis comparison.",
    "provenance": {
      "refs": [
        {
          "source_id": "P008",
          "role": "SUPPORT"
        },
        {
          "source_id": "P010",
          "role": "SUPPORT"
        },
        {
          "source_id": "P029",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the comparison procedure, the nested-span restriction and the risk from overlapping or dependent measurements."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C021_stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The restriction is warranted without establishing an additional unresolved empirical relation."
    }
  },
  "rationale": "Nested spans share execution structure and may include the same elapsed time or underlying event. Counting them as independent corroboration can overstate evidence against or for a hypothesis. The restriction is therefore licensed while preserving their use as dependent observations.",
  "uncertainty": "The degree of dependence can vary; the claim does not require nested spans to be identical or uninformative.",
  "anomalies": []
}
